typedef struct {
    unsigned char* encrypted_data;
    size_t encrypted_len;
    unsigned char* iv;
    unsigned char* key;
} encryption_result;

encryption_result encrypt_data(
    const unsigned char* key, size_t key_len,
    const unsigned char* data, size_t data_len
) {
    // Choose AES-256-CBC as the algorithm
    size_t aes_key_len = 32;
    size_t aes_block_size = AES_BLOCK_SIZE;

    // Extract the AES key from the provided key
    unsigned char aes_key[aes_key_len];
    memcpy(aes_key, key, aes_key_len);

    // Generate IV
    unsigned char iv[AES_BLOCK_SIZE];
    RAND_bytes(iv, AES_BLOCK_SIZE);

    // Allocate memory for encrypted data
    size_t encrypted_len = data_len;
    unsigned char* encrypted_data = (unsigned char*)malloc(encrypted_len);

    // Initialize AES context
    AES_KEY aes_key_ctx;
    AES_set_encrypt_key(aes_key, aes_key_len * 8, &aes_key_ctx);

    // Encrypt data in CBC mode
    AES_cbc_encrypt(data, encrypted_data, data_len, &aes_key_ctx, iv, AES_ENCRYPT);

    // Prepare result
    encryption_result result;
    result.encrypted_data = encrypted_data;
    result.encrypted_len = encrypted_len;
    result.iv = (unsigned char*)malloc(AES_BLOCK_SIZE);
    memcpy(result.iv, iv, AES_BLOCK_SIZE);
    result.key = (unsigned char*)malloc(aes_key_len);
    memcpy(result.key, aes_key, aes_key_len);

    return result;
}

int main() {
    // Example usage
    unsigned char key[32] = {0}; // 256-bit key
    unsigned char data[] = "Hello, World!";
    size_t data_len = sizeof(data) - 1;

    encryption_result result = encrypt_data(key, 32, data, data_len);

    // Print encrypted data
    printf("Encrypted data (hex):\n");
    for (size_t i = 0; i < result.encrypted_len; i++) {
        printf("%02x ", result.encrypted_data[i]);
    }
    printf("\n");

    // Print IV
    printf("IV (hex):\n");
    for (size_t i = 0; i < AES_BLOCK_SIZE; i++) {
        printf("%02x ", result.iv[i]);
    }
    printf("\n");

    // Print key
    printf("Key (hex):\n");
    for (size_t i = 0; i < 32; i++) {
        printf("%02x ", result.key[i]);
    }
    printf("\n");

    // Free allocated memory
    free(result.encrypted_data);
    free(result.iv);
    free(result.key);

    return 0;
}
